{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Tetrabenazine, the closest retrieved analogue (Morgan 0.3731), has a mean absolute oral bioavailability of only 4.9% in patients, demonstrating very extensive first-pass metabolism for a dimethoxy-substituted lipophilic amine scaffold; this directly supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Almorexant, a dimethoxy-tetrahydroisoquinoline amide with a basic amine, has an absolute oral bioavailability of 11.2% in healthy subjects, supporting low systemic availability for the query's amide-containing dimethoxy scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Donepezil, a dimethoxy-substituted CNS drug, has oral bioavailability approaching 100%; however, its smaller, less lipophilic, single-dimethoxy scaffold limits transferability to the larger bis-dimethoxy query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C14"],
      "claim": "Valbenazine, a tetrabenazine prodrug, has approximately 49% absolute oral bioavailability, but this reflects a prodrug ester strategy that is absent in the query, so it does not outweigh the low-F tetrabenazine evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the closest analogue tetrabenazine has very low absolute oral bioavailability (~5%), and the structurally related amide almorexant also shows ~11% F. High-F analogues (donepezil, valbenazine) are less transferable because of a smaller scaffold or prodrug design. The query's two dimethoxyaryl groups and lactam/tertiary-amine framework are consistent with extensive first-pass metabolism and low F.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "Morgan similarities are modest (0.25-0.37), leaving structural uncertainty.",
    "Lack of metabolic stability or permeability data for the exact scaffold.",
    "Verapamil evidence is borderline and does not clearly resolve the F >= 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

